<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: #f1f5f9;
    color: #0f172a;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
  }
  .app-header {
    background: #ffffff;
    border-bottom: 1px solid #e2e8f0;
    padding: 16px 24px;
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
  }
  .app-header h1 { font-size: 22px; font-weight: 700; margin-right: 12px; }
  #new-card {
    flex: 1;
    min-width: 200px;
    max-width: 420px;
    padding: 10px 12px;
    border: 1px solid #cbd5e1;
    border-radius: 8px;
    font-size: 14px;
    outline: none;
  }
  #new-card:focus { border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59,130,246,.2); }
  #add-card {
    padding: 10px 18px;
    background: #2563eb;
    color: #fff;
    border: none;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
  }
  #add-card:hover { background: #1d4ed8; }
  #add-card:active { background: #1e40af; }
  .board {
    display: flex;
    gap: 16px;
    padding: 20px 24px 32px;
    align-items: flex-start;
    justify-content: center;
    flex-wrap: wrap;
  }
  .column {
    flex: 1 1 260px;
    max-width: 380px;
    min-width: 260px;
    background: #e2e8f0;
    border-radius: 12px;
    padding: 12px;
    min-height: 300px;
    display: flex;
    flex-direction: column;
  }
  .col-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 8px 12px;
  }
  .col-header h2 {
    font-size: 15px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .04em;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
  .dot.todo { background: #64748b; }
  .dot.doing { background: #f59e0b; }
  .dot.done { background: #10b981; }
  .count {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    color: #334155;
    font-size: 13px;
    font-weight: 700;
    min-width: 28px;
    height: 24px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    padding: 0 8px;
  }
  .card-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-height: 200px;
    border-radius: 8px;
    padding: 2px;
  }
  .column.drag-over { outline: 2px dashed #2563eb; outline-offset: 2px; background: #dbeafe; }
  .card {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    padding: 12px 12px;
    box-shadow: 0 1px 2px rgba(15,23,42,.08), 0 4px 12px rgba(15,23,42,.06);
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
    cursor: grab;
    font-size: 14px;
    line-height: 1.4;
    word-break: break-word;
  }
  .card:active { cursor: grabbing; }
  .card.dragging { opacity: .5; }
  .card-title { flex: 1; }
  .card-del {
    flex-shrink: 0;
    width: 26px;
    height: 26px;
    border-radius: 6px;
    border: 1px solid #fecaca;
    background: #fef2f2;
    color: #dc2626;
    font-size: 16px;
    line-height: 1;
    cursor: pointer;
  }
  .card-del:hover { background: #fee2e2; }
</style>
</head>
<body>
<header class="app-header">
  <h1>Kanban</h1>
  <input id="new-card" type="text" placeholder="Enter card title..." autocomplete="off">
  <button id="add-card" type="button">Add Card</button>
</header>
<main class="board">
  <section id="col-todo" class="column">
    <div class="col-header"><h2><span class="dot todo"></span>To Do</h2><span class="count">0</span></div>
    <div class="card-list"></div>
  </section>
  <section id="col-doing" class="column">
    <div class="col-header"><h2><span class="dot doing"></span>Doing</h2><span class="count">0</span></div>
    <div class="card-list"></div>
  </section>
  <section id="col-done" class="column">
    <div class="col-header"><h2><span class="dot done"></span>Done</h2><span class="count">0</span></div>
    <div class="card-list"></div>
  </section>
</main>
<script>
(function() {
  var STORAGE_KEY = 'kanban-board-state-v1';
  var input = document.getElementById('new-card');
  var addBtn = document.getElementById('add-card');
  var columns = [
    document.getElementById('col-todo'),
    document.getElementById('col-doing'),
    document.getElementById('col-done')
  ];
  var draggedCard = null;
  var draggedId = null;
  var idCounter = Date.now();

  function nextId() {
    idCounter += 1;
    return 'card-' + idCounter + '-' + Math.floor(Math.random() * 1000000);
  }

  function updateCounts() {
    columns.forEach(function(col) {
      var c = col.querySelectorAll('.card').length;
      var el = col.querySelector('.count');
      if (el) el.textContent = String(c);
    });
  }

  function saveBoard() {
    var data = [];
    columns.forEach(function(col) {
      var cards = col.querySelectorAll('.card');
      cards.forEach(function(card) {
        var titleEl = card.querySelector('.card-title');
        var title = titleEl ? titleEl.textContent : card.textContent;
        data.push({ id: card.id || card.getAttribute('data-id') || '', title: title, column: col.id });
      });
    });
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    } catch (e) {}
  }

  function handleDragStart(e) {
    var card = e.target && e.target.closest ? e.target.closest('.card') : null;
    if (!card) return;
    draggedCard = card;
    draggedId = card.id;
    card.classList.add('dragging');
    try {
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', card.id);
    } catch (err) {}
  }

  function handleDragEnd(e) {
    var card = e.target && e.target.closest ? e.target.closest('.card') : null;
    if (card) card.classList.remove('dragging');
    columns.forEach(function(c) { c.classList.remove('drag-over'); });
  }

  function createCard(title, id) {
    var cardId = id || nextId();
    var card = document.createElement('div');
    card.className = 'card';
    card.id = cardId;
    card.setAttribute('id', cardId);
    card.setAttribute('draggable', 'true');
    card.draggable = true;

    var span = document.createElement('span');
    span.className = 'card-title';
    span.textContent = title;

    var del = document.createElement('button');
    del.className = 'card-del';
    del.type = 'button';
    del.textContent = '\u00d7';
    del.setAttribute('aria-label', 'Delete card');
    del.addEventListener('click', function(ev) {
      ev.stopPropagation();
      card.remove();
      updateCounts();
      saveBoard();
    });

    card.appendChild(span);
    card.appendChild(del);

    card.addEventListener('dragstart', handleDragStart);
    card.addEventListener('dragend', handleDragEnd);

    return card;
  }

  function addCardToTodo() {
    var text = input.value.trim();
    if (!text) return;
    var card = createCard(text);
    var list = document.querySelector('#col-todo .card-list');
    (list || document.getElementById('col-todo')).appendChild(card);
    input.value = '';
    input.focus();
    updateCounts();
    saveBoard();
  }

  addBtn.addEventListener('click', addCardToTodo);
  input.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') addCardToTodo();
  });

  columns.forEach(function(col) {
    col.addEventListener('dragstart', function(e) {
      if (e.target && e.target.classList && e.target.classList.contains('card')) {
        handleDragStart(e);
      }
    });
    col.addEventListener('dragend', function(e) {
      handleDragEnd(e);
    });
    col.addEventListener('dragover', function(e) {
      e.preventDefault();
      try { e.dataTransfer.dropEffect = 'move'; } catch (err) {}
      col.classList.add('drag-over');
    });
    col.addEventListener('dragenter', function(e) {
      e.preventDefault();
    });
    col.addEventListener('dragleave', function(e) {
      if (e.target === col) col.classList.remove('drag-over');
    });
    col.addEventListener('drop', function(e) {
      e.preventDefault();
      col.classList.remove('drag-over');
      var id = null;
      try {
        if (e.dataTransfer) id = e.dataTransfer.getData('text/plain');
      } catch (err) {}
      if (!id) id = draggedId;
      var card = (id && document.getElementById(id)) || draggedCard;
      if (card) {
        var list = col.querySelector('.card-list');
        if (list) list.appendChild(card);
        else col.appendChild(card);
        card.classList.remove('dragging');
        updateCounts();
        saveBoard();
      }
      draggedCard = null;
      draggedId = null;
    });
  });

  function loadBoard() {
    var raw = null;
    try { raw = localStorage.getItem(STORAGE_KEY); } catch (e) {}
    if (!raw) { updateCounts(); return; }
    try {
      var data = JSON.parse(raw);
      if (!Array.isArray(data)) { updateCounts(); return; }
      data.forEach(function(item) {
        if (!item || typeof item.title !== 'string') return;
        var colId = item.column || 'col-todo';
        var col = document.getElementById(colId);
        if (!col) col = document.getElementById('col-todo');
        var card = createCard(item.title, item.id || nextId());
        var list = col.querySelector('.card-list');
        if (list) list.appendChild(card);
        else col.appendChild(card);
      });
    } catch (e) {}
    updateCounts();
  }

  loadBoard();
})();
</script>
</body>
</html>
